SELECT P.JEITO COD, COUNT(*) QTD FROM PRATICAS P JOIN VIDEOS V ON V.ID = P.VIDEO_ID WHERE V.STATUS = 'ESTUDADO' AND P.CONSELHO = 0 AND ({{canalId}} = 0 OR V.CANAL_ID = {{canalId}}) AND ('{{busca}}' = '' OR CONCAT(P.TITULO, ' ', P.INSTRUCAO) COLLATE utf8mb4_0900_ai_ci LIKE CONCAT('%', '{{busca}}', '%')) AND ('{{serve}}' = '' OR FIND_IN_SET('{{serve}}', P.SERVE) OR (LOCATE('.', '{{serve}}') = 0 AND CONCAT(',', P.SERVE) LIKE CONCAT('%,', '{{serve}}', '.%'))) AND ('{{quando}}' = '' OR FIND_IN_SET('{{quando}}', P.QUANDO)) GROUP BY P.JEITO